@Override public void createPaymentAccount(CreatePaymentAccountRequest req, StreamObserver<CreatePaymentAccountReply> responseObserver) {
  try {
    PaymentAccount paymentAccount = coreApi.createPaymentAccount(req.getPaymentAccountForm());
    var reply = CreatePaymentAccountReply.newBuilder()
        .setPaymentAccount(paymentAccount.toProtoMessage())
        .build();
    responseObserver.onNext(reply);
    responseObserver.onCompleted();
  } catch (RuntimeException e) {
    // Log the exception and send an error response
    System.err.println("An error occurred while creating the payment account: " + e.getMessage());
    responseObserver.onError(io.grpc.Status.INTERNAL
        .withDescription("Internal server error: " + e.getMessage())
        .asRuntimeException());
  }
}
